cat > resources/book.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`
    SELECT b.id, b.title, a.name AS author, b.published
    FROM book b
    LEFT JOIN author a ON a.id = b.author_id
    WHERE b.published`;
}
EOF
cat > resources/book.command.ts <<'EOF'
// A book whose author has no name cannot be published.
function authorName(ctx, authorId) {
  const rows = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${authorId}`);
  if (rows.length === 0) {
    ctx.reject({ message: `author ${authorId} does not exist`, pointer: "/author_id", hint: "Create the author first with POST /authors.", status: 422 });
  }
  return rows[0].name;
}

function hasName(name) {
  return name !== null && name !== undefined && String(name).trim() !== "";
}

export function create(input, ctx) {
  const name = authorName(ctx, input.author_id);
  const published = input.published === true;
  if (published && !hasName(name)) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Use an author with a name, or create the book unpublished.", status: 422 });
  }
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${published}) RETURNING id`);
  return row.id;
}

export function update(input, ctx) {
  const [current] = ctx.db.query(ctx.sql`SELECT author_id, published FROM book WHERE id = ${ctx.id}`);
  const authorId = "author_id" in input ? input.author_id : current.author_id;
  const published = "published" in input ? input.published : current.published;
  const name = authorName(ctx, authorId);
  if (published && !hasName(name)) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Use an author with a name, or unpublish the book.", status: 422 });
  }
  if ("title" in input) {
    ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  }
  if ("author_id" in input) {
    ctx.db.exec(ctx.sql`UPDATE book SET author_id = ${input.author_id} WHERE id = ${ctx.id}`);
  }
  if ("published" in input) {
    ctx.db.exec(ctx.sql`UPDATE book SET published = ${input.published} WHERE id = ${ctx.id}`);
  }
}

export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM book WHERE id = ${ctx.id}`);
}
EOF
